using Azure.Identity;
using Azure.Storage.Blobs;

var credential = new DefaultAzureCredential();

// Blob Storage with token credential
var blobUri = new Uri("https://demostorage.blob.core.windows.net");
var blobService = new BlobServiceClient(blobUri, credential);

// Key Vault with the same credential type
var keyVaultUri = new Uri("https://demo-vault.vault.azure.net/");
var secretClient = new Azure.Security.KeyVault.Secrets.SecretClient(keyVaultUri, credential);

using Azure.Storage.Blobs;
using Azure.Security.KeyVault.Secrets;

var builder = WebApplication.CreateBuilder(args);

// Register BlobServiceClient
builder.Services.AddAzureClients(clientBuilder =>
{
    clientBuilder.AddBlobServiceClient(
        builder.Configuration["Azure:Storage:BlobUri"]!);

    clientBuilder.AddSecretClient(
        new Uri(builder.Configuration["Azure:KeyVault:Uri"]!));
});

var app = builder.Build();
app.MapGet("/", () => "Azure SDK ready");
app.Run();
